from __future__ import annotations

import base64
import struct

import pytest

from flighty_mcp import proto
from flighty_mcp.errors import FlightyError


def test_empty_sync_has_no_mutations() -> None:
    assert proto.encode("SyncRequestProto", {"changes": []}) == b""


def test_string_request_matches_independent_wire_fixture() -> None:
    # field 1, wire 2, four bytes of ASCII; not generated by the codec under test.
    assert proto.encode("UserLinkRequestProto", {"token": "fake"}) == bytes.fromhex("0a0466616b65")


def test_double_coordinates_match_ieee754_wire() -> None:
    wire = b"\x09" + struct.pack("<d", -12.5) + b"\x11" + struct.pack("<d", 130.25)
    assert proto.decode("RemoteLocation", wire) == {"latitude": -12.5, "longitude": 130.25}
    assert proto.encode("RemoteLocation", {"latitude": -12.5, "longitude": 130.25}) == wire


def test_negative_int32_is_not_an_unsigned_64_bit_value() -> None:
    value = proto.decode("RemoteFlight.AirportDelay", b"\x08" + b"\xff" * 9 + b"\x01")
    assert value["averageDelayMinutes"] == -1


def test_packed_repeated_enum() -> None:
    # tmiType = [GROUND_STOP, GROUND_DELAY] encoded as two packed varints.
    value = proto.decode("RemoteFlight.FaaPlannedInitiative", b"\x0a\x02\x00\x01")
    assert value["tmiType"] == ["GROUND_STOP", "GROUND_DELAY"]


def test_unpacked_repeated_enum_is_also_accepted() -> None:
    assert proto.decode("RemoteFlight.FaaPlannedInitiative", b"\x08\x00\x08\x01")["tmiType"] == [
        "GROUND_STOP",
        "GROUND_DELAY",
    ]


def test_optional_zero_has_presence() -> None:
    payload = {"active": False}
    # EditPushSettingChangeAction.active isn't optional, so false defaults away.
    assert (
        proto.decode(
            "SyncChangeRequestProto.EditPushSettingChangeAction",
            proto.encode("SyncChangeRequestProto.EditPushSettingChangeAction", payload),
        )
        == {}
    )
    name = next(
        n
        for n, d in proto.SCHEMA.items()
        if d["kind"] == "message"
        and any(f["type"] == "uint32" and f["optional"] for f in d["fields"])
    )
    field = next(f for f in proto.SCHEMA[name]["fields"] if f["type"] == "uint32" and f["optional"])
    assert proto.decode(name, proto.encode(name, {field["json_name"]: 0}))[field["json_name"]] == 0


def test_map_and_timestamp_json_conventions() -> None:
    name = "CreateUserRequestProto"
    assert proto.decode(name, proto.encode(name, {"clientFeatureFlags": {"example": "on"}}))[
        "clientFeatureFlags"
    ] == {"example": "on"}
    payload = {
        "timestamp": "2000-01-01T01:00:00+01:00",
        "flightSetMineAction": {"flightId": "example"},
    }
    assert (
        proto.decode("SyncChangeRequestProto", proto.encode("SyncChangeRequestProto", payload))[
            "timestamp"
        ]
        == "2000-01-01T00:00:00Z"
    )


def test_bytes_round_trip_as_base64() -> None:
    data = base64.b64encode(b"synthetic binary\x00\xff").decode()
    assert proto.decode(
        "SyncChangeRequestProto.ProfileUploadAvatarAction",
        proto.encode("SyncChangeRequestProto.ProfileUploadAvatarAction", {"imageData": data}),
    ) == {"imageData": data}


def test_storage_oneofs_resolved_including_id_variants() -> None:
    value = {
        "airlineId": "example-airline",
        "departure": {
            "airportId": "example-airport",
            "predicted": {"gate": "A1", "isUnlocked": True},
        },
    }
    assert proto.decode("RemoteFlight", proto.encode("RemoteFlight", value)) == value
    with pytest.raises(FlightyError):
        proto.encode("RemoteFlight", {"airlineId": "x", "airline": {"id": "y"}})


@pytest.mark.parametrize(
    "payload",
    [{"noSuchField": 1}, {"flightNumberSearch": {}, "routeSearchProto": {}}, {"departureDate": 42}],
)
def test_unknown_fields_and_conflicting_oneofs_rejected(payload: dict) -> None:
    with pytest.raises(FlightyError):
        proto.encode("SearchRequestProto", payload)


def test_unknown_response_fields_are_detected_and_preserved() -> None:
    wire = b"\xa0\x06\x01"  # unknown field 100, varint 1
    message = proto.parse("SyncResponseProto", wire)
    assert proto.unknown_fields_present(message)
    assert message.SerializeToString() == wire


def test_malformed_wire_fails_safely() -> None:
    with pytest.raises(FlightyError, match="Response does not match"):
        proto.decode("SyncResponseProto", b"\x0a\xff")


def test_parse_error_does_not_echo_secrets() -> None:
    secret = "SYNTHETIC-PRIVATE-VALUE"
    with pytest.raises(FlightyError) as error:
        proto.encode("SyncRequestProto", {"changes": secret})
    assert secret not in str(error.value)


def test_recursive_redaction() -> None:
    data = {
        "nested": [{"token": "fake", "pushToken": "fake", "secret": "fake", "name": "visible"}],
        "storekit1Receipt": "fake",
    }
    assert proto.redact(data) == {
        "nested": [
            {
                "token": "[REDACTED]",
                "pushToken": "[REDACTED]",
                "secret": "[REDACTED]",
                "name": "visible",
            }
        ],
        "storekit1Receipt": "[REDACTED]",
    }


def test_every_contract_builds_and_all_references_resolve() -> None:
    for name, definition in proto.SCHEMA.items():
        if definition["kind"] == "message":
            assert proto.decode(name, proto.encode(name, {})) == {}
    assert len(proto.SCHEMA) == 325


def test_schema_description_and_unknown_name_search() -> None:
    assert proto.describe("NoSuchType")["matches"] == []
    assert proto.describe("RemoteTicket.CabinClass")["kind"] == "enum"
    assert "SyncRequestProto" in proto.describe("SyncRequest")["matches"]
